<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Api\Concerns\RespondsWithApi; use App\Http\Controllers\Controller; use App\Models\Conversation; use Illuminate\Http\Request;
class ChatController extends Controller { use RespondsWithApi; private function participant(Request $r,Conversation $c): Conversation {abort_unless($c->participants()->whereKey($r->user()->id)->exists(),403,'You are not a conversation participant.');return $c;} public function index(Request $r){$items=$r->user()->conversations()->with(['business:id,name','messages'=>fn($q)=>$q->latest('sent_at')->limit(1)])->orderByDesc('conversations.last_message_at')->paginate($r->integer('per_page',20));return $this->success($items->items(),'Success',200,['current_page'=>$items->currentPage(),'per_page'=>$items->perPage(),'total'=>$items->total(),'total_pages'=>$items->lastPage()]);} public function show(Request $r,Conversation $conversation){$conversation=$this->participant($r,$conversation);$messages=$conversation->messages()->with('sender:id,name,avatar_url')->latest('id')->cursorPaginate($r->integer('per_page',30));return $this->success(['conversation'=>$conversation->load('business:id,name','participants:id,name,avatar_url'),'messages'=>$messages->items()],'Success',200,['next_cursor'=>optional($messages->nextCursor())->encode(),'per_page'=>$messages->perPage()]);} }
